#!/usr/bin/env bash
# apply-image-fix.sh · EcoWoods
# FIX: production (Vercel monorepo) does not serve apps/web/public/*, so the 36
# gallery photos 404 on ecowoods.ca (the pre-existing brand logo 404s too).
# This bundles the images via static imports into _next/static — which Vercel
# ALWAYS serves — so they work identically on local dev AND production.
# No file moves, no Vercel dashboard changes. Idempotent.
set -euo pipefail
[[ -f pnpm-workspace.yaml && -d apps/web ]] || { echo "X run from repo root"; exit 1; }
D=apps/web/app/data
[[ -f "$D/floors.ts" ]] || { echo "X $D/floors.ts missing — run apply-everything.sh first"; exit 1; }
imgs=$(find apps/web/public/gallery -name '*.webp' 2>/dev/null | wc -l | tr -d ' ')
[[ "$imgs" -ge 36 ]] || { echo "X need 36 images in apps/web/public/gallery (found $imgs)"; exit 1; }

echo ">> Writing data/floor-images.ts (static import map)"
base64 -d > "$D/floor-images.ts" <<'B64_FI'

B64_FI

echo ">> Pointing floors.ts at the bundled images"
node - "$D/floors.ts" <<'NODE'
const fs=require('fs'); const p=process.argv[2]; let s=fs.readFileSync(p,'utf8');
if(!s.includes("from './floor-images'")) s = "import { FLOOR_IMAGES } from './floor-images';\n" + s;
const old = "const g = (slug: string, shot: 'room' | 'detail' | 'lifestyle') =>\n"
  + "  `/gallery/${slug}-${shot === 'room' ? '01-room' : shot === 'detail' ? '02-detail' : '03-lifestyle'}.webp`;\n\n"
  + "export const floorImages = (slug: string) => ({\n"
  + "  room: g(slug, 'room'),\n  detail: g(slug, 'detail'),\n  lifestyle: g(slug, 'lifestyle'),\n});";
const neu = "export const floorImages = (slug: string) => FLOOR_IMAGES[slug];";
if (s.includes(old)) s = s.replace(old, neu);
fs.writeFileSync(p,s);
console.log('   -> floorImages bundled:', s.includes('FLOOR_IMAGES[slug]') && !s.includes('const g ='));
NODE
echo "OK  Done. rm -rf apps/web/.next && pnpm --filter web dev   (then commit + push to redeploy)"
